schema:
CREATE TABLE Bar (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Beer (
    name VARCHAR NOT NULL,
    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Bar (name, address) VALUES ('BarA', '123 Main St');
INSERT INTO Bar (name, address) VALUES ('BarB', '456 Oak Ave');
INSERT INTO Beer (name, brewer) VALUES ('Corona', 'Grupo Modelo');
INSERT INTO Drinker (name, address) VALUES ('Alice', '789 Pine Ln');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'BarA', 3);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'BarB', 2);
INSERT INTO Serves (bar, beer, price) VALUES ('BarA', 'Corona', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('BarB', 'Corona', 5.50);

